def md5(d): return hashlib.md5(d).hexdigest()

def detect(data):
    if len(data) != ROM_SIZE: return None
    h = md5(data)
    for k,v in VARIANTS.items():
        if h == v["src_md5"]: return k, "src"
    for k,v in VARIANTS.items():
        if h == v["dst_md5"]: return k, "dst"
    return None, h

def apply_patch(src, key):
    rom = bytearray(src)
    for off, hexdata, desc in VARIANTS[key]["regions"]:
        data = bytes.fromhex(hexdata)
        rom[off:off+len(data)] = data
    return bytes(rom)

def main(argv):
    args=[a for a in argv[1:] if a != "--force"]
    force="--force" in argv[1:]
    if not args or args[0] in ("-h","--help"):
        print(__doc__); return 0
    src_path=args[0]
    if len(args)>2:
        print("用法: python build_rom_ws.py <source.ws|.wsc> [output] [--force]"); return 2
    data=open(src_path,"rb").read()
    key,state=detect(data)
    if key is None:
        print("未识别的 ROM: size=%d MD5=%s" % (len(data), state))
        for k,v in VARIANTS.items(): print("  %-3s %-30s src MD5 %s" % (k,v["version"],v["src_md5"]))
        return 2
    v=VARIANTS[key]
    if state=="dst":
        print("已是跳过动画版 (%s): %s" % (key,v["version"])); print("MD5:",v["dst_md5"]); return 0
    out_path=args[1] if len(args)==2 else os.path.join(os.path.dirname(os.path.abspath(src_path)), v["out_name"])
    if os.path.abspath(out_path)==os.path.abspath(src_path):
        print("输出路径不能覆盖输入 ROM"); return 2
    if os.path.exists(out_path) and not force:
        if md5(open(out_path,"rb").read())==v["dst_md5"]:
            print("输出已存在且一致:",out_path); return 0
        print("输出已存在，使用 --force 覆盖:",out_path); return 2
    print("识别:",key,v["version"])
    out=apply_patch(data,key); got=md5(out)
    print("输出 MD5:",got)
    if got!=v["dst_md5"]:
        print("内部校验失败: 期望",v["dst_md5"]); return 3
    open(out_path,"wb").write(out)
    print("已写入:",out_path)
    print("CRC32 输出: %08X" % (zlib.crc32(out)&0xFFFFFFFF))
    return 0

if __name__=="__main__":
    sys.exit(main(sys.argv))
